custom_css:
@media (min-width: 1101px) {
  #evolution {
    display: grid !important;
    box-sizing: border-box !important;
    width: 100% !important;
    height: 900px !important;
    min-height: 900px !important;
    max-height: 900px !important;
    padding: 72px 0 !important;
    align-items: center !important;
    align-content: center !important;
  }

  #evolution .evolution-grid {
    display: grid !important;
    grid-template-rows: auto auto !important;
    row-gap: 24px !important;
    margin: 0 auto !important;
    padding: 0 !important;
    align-content: center !important;
  }

  #evolution .roadmap-copy {
    margin: 0 !important;
    padding: 0 !important;
  }

  #evolution .roadmap-copy .eyebrow {
    margin: 0 0 12px !important;
  }

  #evolution .roadmap-copy h2 {
    margin: 0 0 22px !important;
  }

  #evolution .roadmap-copy p:not(.eyebrow) {
    margin: 0 !important;
  }

  #evolution .prototype-timeline {
    display: grid !important;
    grid-template-columns: repeat(4, minmax(0, 1fr)) !important;
    column-gap: 48px !important;
    row-gap: 28px !important;
    margin: 0 !important;
    padding: 0 !important;
    align-items: start !important;
  }

  #evolution .prototype-timeline li {
    min-height: 0 !important;
    margin: 0 !important;
    padding: 0 !important;
    border: 0 !important;
    align-self: start !important;
  }

  #evolution .prototype-timeline li::before,
  #evolution .prototype-timeline li::after,
  #evolution::before,
  #evolution::after {
    display: none !important;
    content: none !important;
    border: 0 !important;
  }

  #evolution .prototype-timeline span {
    margin-bottom: 8px !important;
  }

  #evolution .prototype-timeline strong {
    margin-bottom: 6px !important;
  }

  #evolution .prototype-timeline p {
    margin: 0 !important;
  }

  #evolution .evolution-close {
    display: none !important;
    margin: 0 !important;
    padding: 0 !important;
    border: 0 !important;
  }
}

@media (max-width: 1100px) {
  #evolution::before,
  #evolution::after {
    display: none !important;
    content: none !important;
  }
}
